<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mount Fuji Dusk — Chureito Pagoda</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;1,400&display=swap" rel="stylesheet">
<style>
  html,body{margin:0;height:100%;overflow:hidden;background:#1a1030}
  #c{display:block;width:100%;height:100%}
  .title{
    position:fixed;left:4vw;bottom:6vh;color:#ffe9f2;pointer-events:none;
    font-family:'Cormorant Garamond',serif;
    text-shadow:0 2px 18px rgba(20,10,40,.8);
    user-select:none;
  }
  .title h1{margin:0;font-weight:500;font-size:clamp(28px,4.5vw,54px);letter-spacing:.06em}
  .title p{margin:.35em 0 0;font-style:italic;font-size:clamp(13px,1.4vw,18px);opacity:.75;letter-spacing:.12em}
</style>
</head>
<body>
<canvas id="c"></canvas>
<div class="title"><h1>Chureito · Mount Fuji</h1><p>桜と黄昏 — dusk in full bloom</p></div>
<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

/* ---------- renderer / scene / camera ---------- */
const canvas = document.getElementById('c');
const renderer = new THREE.WebGLRenderer({canvas, antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth, innerHeight);

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x4a2f66, 0.0011);

const camera = new THREE.PerspectiveCamera(38, innerWidth/innerHeight, .1, 4000);

/* dusk palette */
const P = {
  skyTop:0x241245, skyMid:0x6b3f7a, skyLow:0xd97a6a, horizon:0xf2a68c,
  fuji:0x4a3a6e, snow:0xf3e6ef, snowLit:0xffd9e0,
  pagodaRed:0xa63a2f, pagodaDark:0x6e241d, roof:0x35204a,
  trunk:0x4a2f33, blossomA:0xf5a8c4, blossomB:0xfbcfe0,
  ground:0x453465, water:0x3a2a5e, sun:0xffcf9e
};

/* ---------- sky dome (vertex-colored gradient, dusk) ---------- */
{
  const geo = new THREE.SphereGeometry(1600, 32, 24);
  const cols = [];
  const pos = geo.attributes.position;
  const cTop = new THREE.Color(P.skyTop), cMid = new THREE.Color(P.skyMid),
        cLow = new THREE.Color(P.skyLow), cHor = new THREE.Color(P.horizon);
  for (let i=0;i<pos.count;i++){
    const y = pos.getY(i)/1600; // -1..1
    const c = new THREE.Color();
    if (y > 0.25)      c.copy(cMid).lerp(cTop, Math.min((y-0.25)/0.75,1));
    else if (y > 0.02) c.copy(cLow).lerp(cMid, (y-0.02)/0.23);
    else if (y > -0.05) c.copy(cHor).lerp(cLow, (y+0.05)/0.07);
    else               c.copy(cHor);
    cols.push(c.r,c.g,c.b);
  }
  geo.setAttribute('color', new THREE.Float32BufferAttribute(cols,3));
  const sky = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({vertexColors:true, side:THREE.BackSide, fog:false, depthWrite:false}));
  sky.renderOrder = -1;
  scene.add(sky);
}

/* ---------- lights ---------- */
scene.add(new THREE.HemisphereLight(0xffc4d2, 0x4a3568, 1.35));
const sun = new THREE.DirectionalLight(0xffb08a, 2.4);
sun.position.set(-700, 160, -300);
scene.add(sun);
const rim = new THREE.DirectionalLight(0x9a7aff, 0.8);
rim.position.set(400, 250, 600);
scene.add(rim);

/* ---------- low-poly helper: flat-shaded mesh ---------- */
function lowPoly(geo, color, opts={}){
  geo.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({color, flatShading:true, roughness:0.9, metalness:0, ...opts});
  return new THREE.Mesh(geo, mat);
}

